import { fetchEncryptStream, updStore, getStore, convertArray2Obj, ObjectKeys, callbackOnMemory, convertObj2Array, qryStore, gen16CodeId, isJson, convertArray2ObjGroupby, fetchQueue } from "../../../stores/Utils";




export const getall_invoice = async (cb) => {
    let lastTimeCallModal = getStore("getall_invoice_last") || 0;
    if(Date.now() > lastTimeCallModal){
        updStore("getall_invoice_last", Date.now()+190);
        let bdyq2 = {...getStore(qryStore())?.all_invoices};
        bdyq2.params = {
            businessId:  getStore("profileUser")?.businessId
        }
        const res = fetchEncryptStream(bdyq2);
        const td = await res;
        if (td) {
           
            updStore("invoices_list", sortInvoices(td,"document"));
            updStore("invoices_ids", convertArray2Obj(convertObj2Array(td),"document"));
            cb && cb();
        }
    }
};


