export const sortInvoices = (td, key, order) =>
callbackOnMemory(
	"sortInvoices",
	[td],
	() => {
        
		let sortedA = td && td.sort((a, b) => {
			let A = a[key];
			let B = b[key];
			if (A < B) {
				return order ? -1 : 1;
			}
			if (A > B) {
				return order ? 1 : -1;
			}
			return 0;
        });
		return sortedA;
	}
);






