const calc_comp_invoices =  () => {

    let invoiceCmp =  getStore("invoiceCmp");
    let CXC =  getStore("invoiceCmpSSJsgB2uUqcuoagD");
    let AntC =  getStore("invoiceCmpv5MkYLwPAbgci3wW");


    let docs = {

    }

    ObjectKeys(invoiceCmp).map(regId=>{
       
        let document = invoiceCmp[regId].document.trim();
       
        if(!docs[document]){
            docs[document] = {
                document: document,
                invoiceId: invoiceCmp[regId]?.invoiceId,
                invoiceLinkConfirmed: invoiceCmp[regId]?.invoiceLinkConfirmed,
                amount: 0,
                saldo: 0,
                hasAnticipo: 0,
                cc_c: 0,
                cc_d: 0,
                comprobanteIds: {}  
            }
        }
        docs[document]["amount"] += invoiceCmp[regId].amount;
        docs[document]["saldo"] += invoiceCmp[regId].amount *1;
        docs[document]["date"] = invoiceCmp[regId].date;
        //docs[document]["descriptionInvoice"] += invoiceCmp[regId].description;
    });
    ObjectKeys(CXC).map(regId=>{
        let document = CXC[regId].document.trim();
        if(!docs[document]){
            docs[document] = {
                document: document,
                amount: 0,
                saldo: 0,
                hasAnticipo: 0,
                cc_c: 0,
                cc_d: 0,
                comprobanteIds: {}   
            }
        }
        docs[document]["cc_d"] += CXC[regId]?.type === "debit"? CXC[regId].amount *1 : 0 ;
        docs[document]["cc_c"] += CXC[regId]?.type === "credit"? CXC[regId].amount *1 : 0 ;
        
        docs[document]["saldo"] += CXC[regId]?.type === "credit"? CXC[regId].amount *-1 : 0 ;
        docs[document]["comprobanteIds"][CXC[regId].comprobanteId] = {
            date: CXC[regId].date,
            description: CXC[regId].description
        };
    });
    ObjectKeys(AntC).map(regId=>{

       
        let document = AntC[regId].document.trim();
        if(document.indexOf("A-")>=0){
            document = document.split("A-")[1];
        }
        if(!docs[document]){
            docs[document] = {
                document: document,
                amount: 0,
                hasAnticipo: 0,
                cc_c: 0,
                cc_d: 0,
                saldo: 0,
                comprobanteIds: {}   
            }
        }
        docs[document]["hasAnticipo"] += AntC[regId]?.type === "credit"? AntC[regId].amount *1 : AntC[regId].amount *-1 ;
        docs[document]["saldo"] += (AntC[regId]?.type === "credit"? AntC[regId].amount *1 : AntC[regId].amount *-1 ) *-1;
        docs[document]["comprobanteIds"][AntC[regId].comprobanteId] = {
            date: AntC[regId].date,
            description: AntC[regId].description
        };
    });
   
    return docs;
}










export const loadInvoicesfromFile =  (fileJSON) => {

    let prod = [];

    
    let docM = convertArray2ObjGroupby(getStore("invoices_list"),"document")

    if(isJson(fileJSON)){
        fileJSON = JSON.parse(fileJSON)
    }
   

    console.log({docM})
    fileJSON.map(dpt=>{

        let nfrm = {...dpt}
        let may2024 =( new Date("05/14/2024")).getTime()

        if(nfrm.date>may2024){
            nfrm.invoiceId =  gen16CodeId();
            if( nfrm.invoiceLinkConfirmed && nfrm.amount && nfrm.document && !docM[nfrm.document]){
           
                let bdyq23 = {...getStore(qryStore())?.add_invoice};
                bdyq23.params = {
                    businessId:  getStore("profileUser")?.businessId
                };
                bdyq23.form = nfrm;
                prod.push(bdyq23)  
            }
        }
    })

     
   //console.log({prod})
    fetchQueue(prod, fetchCSVInve)
   
}





