import React, { useEffect, useState, useRef } from "react";

import { getStore, updStore, gen16CodeId, parseDate, fetchPostH, getUrlServerSide, ObjectKeys, hasWritePrivilege, parseDateMMDDYYYY, AccountYears, qryStore, fetchEncryptStream, getLabelTranslate } from "../../../stores/Utils";

import "./dashboard.css"
import { OpenModal } from "../../../components/DialogHRM";
import { getall_invoice, sortInvoices, delete_invoice } from "../services/server_fetching";
import { SvgIcon_Cmpt, TextInput_Cmpt } from "../../../components";
import DeleteAlert from "./deleteAlert";
import NoPrivilege from "./NoPrivilege";
import { ViewInvoice_Cmpt } from "..";
import { AddVoucher_Cmpt } from "../../Inventory";
import { scan_voucherByInvoice } from "../../Inventory/services/server_fetching";
import InvoiceOnVoucher from "./InvoiceOnVoucher";


const Svg = SvgIcon_Cmpt();


const ViewInvoice = ViewInvoice_Cmpt();
const AddVoucher = AddVoucher_Cmpt();


const TextInput = TextInput_Cmpt();




const frmNm = "updDocInvoice"

const InvoiceItem  = ({ data, index, handleRefreshAll, show }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);

	const [edit, set_edit] = useState(0);
	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			
			// let frm2 = {"firstName":"Belisario","lastName":"Gonzalez Arevalo","genre":"Male","dateOfBirth":"06/02/1976","placeOfBirth":{"city":"Holguin","state":"Holguin"},"currentAddress":{"No":"4307","street":"Estate Dr","city":"Louisville","state":"Kentucky","zipcode":"40216"},"dob":202536000000}
			//updStore(frmNm, frm2);
			set_obs(gen16CodeId())
		}
	});

	if(!show){
		return null;
	}
	
	const updObs =  () => {
		set_obs(gen16CodeId())
	}



	const refreshAccs =  () => {
		getall_invoice(updObs)
	}




	const update = async (v) => {

		let bdyqInvoice = {...getStore(qryStore())?.upd_invoice};
		bdyqInvoice.params = {
			businessId:  getStore("profileUser")?.businessId,
			invoiceId: data?.invoiceId
		}
		bdyqInvoice.data2update={document: v};

	
		

		//console.log(bdyqInvoice)
		
		const a2S = 0;
		
		
		if(a2S){
			const res = fetchEncryptStream(bdyqInvoice);
			const td = await res;
			// console.log(td)
			if (td) {
				set_edit(false)
			}
		}
		
	}

	const editDoc =  () => {
			set_edit(!edit)
	}
	


	const openSubMayor =  (sba) => {
		

		let modaldata = {};
		modaldata["zIndex"] = 450;
		modaldata["height"] = "80vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true };
		modaldata["content"] =  <ViewInvoice confirm={refreshAccs} item={data}/>
		OpenModal(modaldata);
	}


	const deleteComprobante =  () => {
		delete_invoice(data?.invoiceId, handleRefreshAll);
	}
	

	const OpenDeleteAlert =  () => {
		let lastTimeCallModal = getStore("lastTimeCallModal") || 0;
		if(hasWritePrivilege()){
			if( Date.now() > lastTimeCallModal){
				updStore("lastTimeCallModal", Date.now()+320);
				let modaldata = {};
				modaldata["zIndex"] = 450;
				modaldata["height"] = "40vh";
				// data['observeResize']=true;
				modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
				modaldata["content"] = <DeleteAlert confirm={deleteComprobante} item={data} />
				OpenModal(modaldata);
			}
		}else{
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "40vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
			modaldata["content"] = <NoPrivilege />
			OpenModal(modaldata);
		}
	}

	

	const openAddVoucherModal =  (v) => {

		//console.log(data)
		//addInv();

		let modaldata = {};
		modaldata["zIndex"] = 450;
		modaldata["height"] = "80vh";
		modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
		if(!v){
			let txt = data?.description.split("Sale to ")[1];

			updStore("new_voucher",{
				invoice: data?.document.trim(),
				invoiceId: data?.invoiceId.trim(),
				clientName: txt.trim(),
			})
			modaldata["content"] =  <AddVoucher />
		}else{
			modaldata["content"] = <InvoiceOnVoucher invoice={data?.document.trim()} />
		}
		OpenModal(modaldata);
	}


	const openAddVoucher =  () => {


		scan_voucherByInvoice(data?.document.trim(),openAddVoucherModal)	

		
	}


	

	return (
		<div className={`item_acc ${index}`} >
			<div className="_dsplFlx item_box invoice_header">
				<div className="name" >
					{parseDateMMDDYYYY(data?.date)} 
				</div>

				<div className="code" style={{marginLeft:15}} onClick={editDoc}>
					{data?.document}
				</div>
				{edit? 
				<div className="_dsplFlx "  style={{margin: "18px 0"}}>
					<div className="flexSpace"/>
					<TextInput  
						init={getStore(frmNm)} 
						label={getLabelTranslate(2)} 
						width={520} 
						updChanges={(e)=>updStore(frmNm,e)}
						onEnter={update}
					/>
					<div className="flexSpace"/>
				</div>
				:null}

				<div className="description" style={{marginLeft:15}}>
					{data?.description}
				</div>
				<div className="flexSpace"/>
				
				<div className="flexSpace"/>
				<div className="_dsplFlx ">
					{AccountYears()[getStore("date_current_year")]?.isClosed?null:
					<div className=" addSbAcc purple" onClick={()=>openAddVoucher(null)}>
						add Voucher
					</div>
					}
					<div className=" addSbAcc purple" onClick={()=>openSubMayor(null)}>
						See Details
					</div>
				</div>
				
				<div className="name hideOnHover">
					${(data?.amount*1).toFixed(2)}
				</div>
				{hasWritePrivilege()?
				AccountYears()[getStore("date_current_year")]?.isClosed?null:
				<div className="icon" style={{marginLeft: 19,zIndex:10}} onClick={OpenDeleteAlert}>
					<Svg name={"outline_delete"} color={"#c62828"}/>
				</div>
				:null}
			</div>
			
		</div>
	)
}
export default InvoiceItem;






